d=f"{R}/res/drawable"
for f in os.listdir(d):
    if f.startswith("ic_k_"): os.remove(os.path.join(d,f))
for name,path in icons.items():
    open(f"{d}/ic_k_{name}.xml","w").write(f'''<?xml version="1.0" encoding="utf-8"?>
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="24dp" android:height="24dp"
    android:viewportWidth="24" android:viewportHeight="24">
    <path android:fillColor="#FFFFFFFF" android:pathData="{path}"/>
</vector>
''')
entries=",\n".join(f'        "{n}" to R.drawable.ic_k_{n}' for n in icons)
open(f"{R}/java/dev/belta/macropad/Icons.kt","w").write(f'''package dev.belta.macropad

// Generated: key icons (24dp vectors in res/drawable/ic_k_*.xml, Material Icons style).
object Icons {{
    val all: Map<String, Int> = linkedMapOf(
{entries},
    )

    fun get(name: String?): Int? = name?.let {{ all[it] }}
}}
''')
print(len(icons),"icons")
